class Solution:
    def trap(self, height):
        size = len(height)
        left_high = height.copy()
        right_high = height.copy()
        for pos in range(1, size):
            left_high[pos] = max(left_high[pos - 1], height[pos])
        for pos in range(size - 2, -1, -1):
