class Solution:
    def merge(self, intervals):
        largest = max(end for _, end in intervals)
        delta = [0] * (2 * largest + 2)
        for begin, end in intervals:
            delta[2 * begin] += 1
            delta[2 * end + 1] -= 1
        answer = []
