class Solution:
    def search(self, nums, target):
        low, high = -1, len(nums) - 1
        while high - low > 1:
            middle = (low + high) // 2
            if nums[middle] < nums[-1]:
                high = middle
            else:
                low = middle
        pivot = high
        if target > nums[-1]:
            low, high = -1, pivot
        else:
            low, high = pivot - 1, len(nums)
        while high - low > 1:
            middle = (low + high) // 2
            if nums[middle] >= target:
                high = middle
            else:
                low = middle
        return high if nums[high] == target else -1

