class MinStack:
    def __init__(self):
        self.differences = []
        self.minimum = inf

    def push(self, val):
        self.differences.append(val - self.minimum)
        self.minimum = min(self.minimum, val)

    def pop(self):
        difference = self.differences.pop()
        if difference < 0:
            self.minimum -= difference

    def top(self):
        return self.minimum + max(0, self.differences[-1])

    def getMin(self):
        return self.minimum

