class Solution:
    def largestRectangleArea(self, heights):
        size = len(heights)
        left, right = [-1] * size, [size] * size
        stack = []
        for pos in range(size):
            while stack and heights[stack[-1]] >= heights[pos]:
                stack.pop()
            if stack:
                left[pos] = stack[-1]
            stack.append(pos)
        stack.clear()
        for pos in range(size - 1, -1, -1):
            while stack and heights[stack[-1]] >= heights[pos]:
                stack.pop()
            if stack:
                right[pos] = stack[-1]
            stack.append(pos)
        return max(heights[pos] * (right[pos] - left[pos] - 1) for pos in range(size))

class Solution:
    def largestRectangleArea(self, heights):
        size = len(heights)
        left, right = [-1] * size, [size] * size
        stack = []
        for pos, value in enumerate(heights):
            while stack and heights[stack[-1]] >= value:
                right[stack.pop()] = pos
            if stack:
                left[pos] = stack[-1]
            stack.append(pos)
        return max(heights[pos] * (right[pos] - left[pos] - 1) for pos in range(size))

class Solution:
    def climbStairs(self, n):
        # 此版本故意保留重复计算，用于说明递归关系
        def ways(steps):
            if steps <= 1:
                return 1
            return ways(steps - 1) + ways(steps - 2)
        return ways(n)

