class Solution:
    def rob(self, nums):
        @cache
        def best(last):
            if last < 0:
                return 0
            return max(best(last - 1), best(last - 2) + nums[last])
        return best(len(nums) - 1)

class Solution:
    def rob(self, nums):
        best = [0] * (len(nums) + 2)
        for index, money in enumerate(nums):
            best[index + 2] = max(best[index + 1], best[index] + money)
        return best[-1]

