class Solution:
    def numSquares(self, n):
        layer = [0]
        visited = [True] + [False] * n
        steps = 0
        while layer:
            following = []
            for total in layer:
                if total == n:
                    return steps
                root = 1
                while total + root * root <= n:
                    value = total + root * root
                    if not visited[value]:
                        visited[value] = True
                        following.append(value)
                    root += 1
            layer = following
            steps += 1

