class Solution:
    def wordBreak(self, s, wordDict):
        words = set(wordDict)
        longest = max(map(len, wordDict))
        @cache
        def possible(end):
            if end == 0:
                return True
            for begin in range(end - 1, max(-1, end - longest - 1), -1):
                if s[begin:end] in words and possible(begin):
                    return True
            return False
        return possible(len(s))

